// Secure version of app.js with security best practices

const express = require('express');
const app = express();

// Initialize environment variables
require('dotenv').config();

// Security middleware
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');

// Security enhancements
app.use(helmet());

// Configure CORS
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : [],
  methods: ['GET'],
  allowedHeaders: ['Content-Type']
}));

// Request logging
const accessLogStream = fs.createWriteStream(path.join(__dirname, 'access.log'), { flags: 'a' });
app.use(morgan('combined', { stream: accessLogStream }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Health endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with basic auth and sanitized output
app.get('/users', (req, res) => {
  // In a real application, validate credentials from req.headers.authorization
  const isAuthenticated = false; // Simplified for this example

  if (isAuthenticated) {
    // Authenticated users get full data
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ]);
  } else {
    // Unauthenticated users get limited data
    res.json([
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' }
    ]);
  }
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  if (err.name === 'UnauthorizedError') {
    res.status(401).json({ error: 'Unauthorized' });
  } else {
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// Secure server configuration
const server = app.listen(3000, () => {
  console.log('Server running securely on port 3000');
});

// Set secure timeout
server.setTimeout(5 * 60 * 1000); // 5 minutes

module.exports = app;

