! .env.example
```

## Phase 2: Implement AWS Secrets Manager Integration

### Update app.js with proper secrets management:

```javascript
const express = require('express');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const app = express();
let cachedSecrets = null;

// Configure secrets manager client with IAM role (not credentials)
const secretsClient = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

async function getSecret(secretName) {
    try {
        const command = new GetSecretValueCommand({ SecretId: secretName });
        const response = await secretsClient.send(command);
        return JSON.parse(response.SecretString);
    } catch (err) {
        console.error(`Failed to retrieve secret ${secretName}:`, err.code || err);
        throw new Error('Secret retrieval failed');
    }
}

async function loadSecrets() {
    if (cachedSecrets) return cachedSecrets;

    try {
        const [dbSecret, awsSecret, apiSecret] = await Promise.all([
            getSecret(process.env.DB_CONFIG_SECRET_NAME),
            getSecret(process.env.AWS_CONFIG_SECRET_NAME),
            getSecret(process.env.API_KEY_SECRET_NAME)
        ]);

        cachedSecrets = { db: dbSecret, aws: awsSecret, api: apiSecret };
        return cachedSecrets;
    } catch (err) {
        console.error('Secret loading failed:', err);
        process.exit(1);
    }
}

// Secure health endpoint
app.get('/health', async (req, res) => {
    try {
        const secrets = await loadSecrets();
        // Use secrets.db or secrets.api as needed
        res.json({ status: 'ok', timestamp: new Date().toISOString() });
    } catch (err) {
        console.error('Health check failed:', err);
        res.status(500).json({ error: 'Service unavailable' });
    }
});

// Other routes remain similar - just wrap in async and load secrets

module.exports = app;
```

