```

## Phase 4: Advanced Security Controls (Week 2)

### Implement secret rotation automation:
```javascript
const { UpdateSecretCommand } = require('@aws-sdk/client-secrets-manager');

async function rotateApiKey(oldKey, newKey) {
    try {
        const currentSecrets = await getSecret('api-keys');
        currentSecrets.ANTHROPIC_API_KEY = newKey;

        const command = new UpdateSecretCommand({
            SecretId: 'api-keys',
            SecretString: JSON.stringify(currentSecrets)
        });

        await secretsClient.send(command);
        console.log('API key rotated successfully');
        return true;
    } catch (err) {
        console.error('Key rotation failed:', err);
        return false;
    }
}
```

## Security Monitoring Configuration

### Add CloudWatch alerts for secret access:
```yaml
# Example CloudWatch alarm
Resources:
  SecretAccessAlarm:
    Type: AWS::CloudWatch::Alarm
    Properties:
      AlarmName: "SecretsManagerAccessAlarm"
      AlarmDescription: "Alert on unexpected secrets access"
